{
  "name": "树莓派 GPIO 舵机（ServoBlaster）",
  "name_en": "Raspberry Pi GPIO Servo (ServoBlaster)",
  "manufacturer": "",
  "description": "通过树莓派 GPIO 配合 ServoBlaster 服务输出 PWM 脉冲来控制舵机位置的执行器接口。适合在实验或机器人装置中进行转向、角度定位和小型机械运动控制。",
  "description_en": "An actuator interface for controlling a servo position by outputting PWM pulses from Raspberry Pi GPIO through the ServoBlaster service. It is suitable for steering, angle positioning, and small mechanical motion control in lab or robotics setups.",
  "actions": [
    {
      "action_name": "auto-set_pulse",
      "description": "设置舵机 PWM 脉宽输出。",
      "description_en": "Set the servo PWM pulse output."
    },
    {
      "action_name": "auto-run",
      "description": "输出指定的舵机脉宽以驱动舵机。",
      "description_en": "Output the specified servo pulse to drive the servo."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭舵机控制输出。",
      "description_en": "Shut down the servo control output."
    }
  ],
  "tag_hints": [
    "servo control",
    "Raspberry Pi GPIO",
    "PWM pulse output",
    "ServoBlaster",
    "motion actuation",
    "angle positioning"
  ]
}

